SELECT md.chembl_id AS molecule_chembl_id, md.pref_name AS molecule_name, md.max_phase, md.molecule_type, cs.canonical_smiles FROM molecule_dictionary md JOIN compound_records cr ON md.molregno = cr.molregno JOIN compound_structures cs ON md.molregno = cs.molregno JOIN chembl_id_lookup cil ON cr.doc_id = cil.entity_id AND cil.entity_type = 'DOCUMENT' WHERE cil.chembl_id = 'CHEMBL1152129' ORDER BY md.chembl_id
